// Helper function to get instances for a specific tag
func getInstancesForTag(instances []*models.AgencyInstance, tagID string) []*models.AgencyInstance {
	var result []*models.AgencyInstance
	for _, inst := range instances {
		if inst.TagID == tagID {
			result = append(result, inst)
		}
	}
	return result
}

// Helper function to get state CSS class
func getStateClass(state models.InstanceState) string {
	switch state {
	case models.InstanceStateRunning:
		return "is-success"
	case models.InstanceStateStopping:
		return "is-warning"
	case models.InstanceStateStopped:
		return "is-light"
	case models.InstanceStateFailed:
		return "is-danger"
	default:
		return "is-light"
	}
}

// Helper function to get health CSS class
func getHealthClass(health string) string {
	switch health {
	case "healthy":
		return "is-success"
	case "degraded":
		return "is-warning"
	case "unhealthy":
		return "is-danger"
	default:
		return "is-light"
	}
}

// Helper function to format uptime
func formatUptime(seconds int64) string {
	if seconds == 0 {
		return "N/A"
	}
	duration := time.Duration(seconds) * time.Second
	hours := int(duration.Hours())
	minutes := int(duration.Minutes()) % 60

	if hours > 0 {
		return fmt.Sprintf("%dh %dm", hours, minutes)
	}
	return fmt.Sprintf("%dm", minutes)
}

